const companies = [
 {name:'NVIDIA', domain:'nvidia.com', careers:'jobs.nvidia.com'},
 {name:'Boston Dynamics', domain:'bostondynamics.com', careers:'bostondynamics.com'},
 {name:'Figure AI', domain:'figure.ai', careers:'figure.ai'},
 {name:'Tesla', domain:'tesla.com', careers:'tesla.com'},
 {name:'Agility Robotics', domain:'agilityrobotics.com', careers:'agilityrobotics.com'}
];
// Derive this map from the single company list. Add new companies above; no fallback domain exists.
const domainMap = Object.fromEntries(companies.map(c => [c.name, c.domain]));
const keywords = [
 'robotics software engineer','robotics engineer','robotics engineer intern','robotics software intern',
 'robotics intern','autonomous systems engineer','perception engineer','computer vision engineer',
 'machine learning engineer','ai engineer','embedded software engineer','controls engineer'
];
const q = companies.map(c => `site:${c.careers} OR site:${c.domain}/careers (${keywords.map(k=>`"${k}"`).join(' OR ')})`).join('\n');
const site = (() => { try { return $('Fetch Portfolio Profile').first().json || {}; } catch (e) { return {}; } })();
// Everything about the owner comes from the portfolio (/api/public/outreach-profile). Env values are only an optional override.
const pick = (a, b, dflt) => String(a || b || dflt || '').trim();
const profile = {
 name: pick($env.PROFILE_NAME, site.name, ''),
 bio: pick($env.PROFILE_BIO, site.bio, ''),
 roles: keywords,
 locationPreference: String($env.LOCATION_PREFERENCE || 'India, remote, global'),
 resumeUrl: pick($env.RESUME_URL, site.resumeUrl, ''),
 portfolioUrl: pick($env.PORTFOLIO_URL, site.portfolioUrl, ''),
 sendingEmail: pick($env.PROFILE_GMAIL, site.email, '')
};
const missing = ['name','bio','resumeUrl','portfolioUrl','sendingEmail'].filter(k => !profile[k]);
if (missing.length) throw new Error('Portfolio profile is incomplete (' + missing.join(', ') + '). Upload the resume in Admin -> Resume Studio and check PORTFOLIO_URL.');
return [{json:{companies,domainMap,keywords,queries:q,profile}}];

const cfg = $('Build Search Config').first().json;
const existing = $('Read Existing Jobs').all().map(x=>x.json);
const seen = new Set(existing.map(r=>String(r['Job Link']||'').trim()).filter(Boolean));
const companies = cfg.companies;
const out = [];
for (const item of $input.all()) {
  const payload = item.json || {};
  const results = payload.organicResults || payload.organic_results || payload.results || [];
  for (const r of results) {
    const url = String(r.url || r.link || r.displayedUrl || '').trim();
    const title = String(r.title || '').trim();
    if (!url || !/^https?:\/\//i.test(url)) continue;
    const host = (()=>{try{return new URL(url).hostname.replace(/^www\./,'').toLowerCase()}catch{return ''}})();
    const co = companies.find(c => host === c.domain || host.endsWith('.'+c.domain) || host === c.careers || host.endsWith('.'+c.careers));
    if (!co) continue;
    const titleText = title.toLowerCase();
    if (!cfg.keywords.some(k => titleText.includes(k))) continue;
    if (seen.has(url)) continue;
    seen.add(url);
    out.push({json:{
      'Job Link':url,'Company':co.name,'Job Title':title,
      Location:String(r.location||r.city||r.jobLocation||'Not specified in search result'),
      'Date Found':new Date().toISOString(),'Status':'Found','Posting Text':'',
      'Contact Name':'','Contact Title':'','Contact Email':'','LinkedIn URL':'',
      'Email Verification':'','Draft':'','Replied':'N','First Sent Date':'',
      'Follow-Up Due Date':'','Follow-Up Sent Date':'','Follow-Up Draft':'',
      'History':'','Last Error':'','Approved At':'','Gmail Message ID':'','Gmail Thread ID':'',
      companyDomain:cfg.domainMap[co.name], profileName:cfg.profile.name, profileBio:cfg.profile.bio,
      profileRoles:cfg.profile.roles, locationPreference:cfg.profile.locationPreference,
      resumeUrl:cfg.profile.resumeUrl, portfolioUrl:cfg.profile.portfolioUrl
    }});
  }
}
return out;

const source = {...$('Append New Job').item.json, ...$('Normalize and Deduplicate Jobs').item.json};
const html = String($json.pageHtml ?? $json.data ?? $json.body ?? $json ?? '');
let text = html
 .replace(/<script[\s\S]*?<\/script>/gi,' ')
 .replace(/<style[\s\S]*?<\/style>/gi,' ')
 .replace(/<noscript[\s\S]*?<\/noscript>/gi,' ')
 .replace(/<[^>]+>/g,' ')
 .replace(/&nbsp;|&#160;/gi,' ')
 .replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>')
 .replace(/&#39;|&apos;/gi,"'").replace(/&quot;/gi,'"')
 .replace(/\s+/g,' ').trim();
const words = text.match(/\b[\p{L}\p{N}][\p{L}\p{N}'’-]*\b/gu) || [];
const usefulText = words.length >= 40;
return [{json:{...source,'Posting Text':usefulText?text:'','postingWordCount':words.length,'postingUsable':usefulText,'postingFailureReason':usefulText?'':'Fetched page returned fewer than 40 useful words or was inaccessible'}}];

const job = $('Extract Posting Text').item.json;
const people = Array.isArray($json.people) ? $json.people : [];
const priorities = [
  {rank:1,re:/\b(hr manager|human resources manager)\b/i},
  {rank:2,re:/\b(talent acquisition|talent partner|recruiting manager)\b/i},
  {rank:3,re:/\b(recruiter|technical recruiter)\b/i},
  {rank:4,re:/\b(hiring manager)\b/i},
  {rank:5,re:/\b(team lead|tech lead|engineering lead)\b/i},
  {rank:6,re:/\b(engineering manager)\b/i}
];
// Search results deliberately do not gate on has_email: Apollo may hide that
// flag until enrichment. Only require a usable person ID and current title.
const candidates = people
  .filter(p => p && p.id && p.title)
  .map(p => {
    const title = String(p.title || '').trim();
    const hit = priorities.find(x => x.re.test(title));
    if (!hit) return null;
    const orgName = String(p.organization_name || p.organization?.name || job.Company || '').trim();
    return {
      id: String(p.id),
      first_name: String(p.first_name || '').trim(),
      last_name: String(p.last_name || '').trim(),
      organization_name: orgName,
      domain: String(job.companyDomain || '').trim(),
      title,
      linkedin_url: String(p.linkedin_url || '').trim(),
      rank: hit.rank
    };
  })
  .filter(Boolean)
  .sort((a,b) => a.rank - b.rank)
  .slice(0,10);
if (!candidates.length) {
  return [{json:{...job,hasCandidates:false,details:[],candidateRanks:[]}}];
}
// Send the ID plus corroborating identity/company fields to improve bulk matching.
const details = candidates.map(c => ({
  id: c.id,
  first_name: c.first_name,
  last_name: c.last_name,
  organization_name: c.organization_name,
  domain: c.domain,
  title: c.title,
  ...(c.linkedin_url ? {linkedin_url:c.linkedin_url} : {})
}));
return [{json:{...job,hasCandidates:true,details,candidateRanks:candidates}}];

const job=$('Rank Apollo Candidates').item.json;
const bulk=$('Apollo Bulk Enrichment').first().json || {};
const matches=Array.isArray(bulk.matches)?bulk.matches:[];
const existing=$('Read Contacts — Current Before Selection').all().map(x=>x.json);
const reservedOrContacted=new Set(existing.filter(r=>{
 const state=String(r['Contact State']||'').toLowerCase();
 return Boolean(String(r['Contacted At']||'').trim()) || ['reserved','contacted','do not contact','opted out'].includes(state) || String(r['Opted Out']||'').toUpperCase()==='Y';
}).map(r=>String(r.Email||r['Contact Email']||'').trim().toLowerCase()).filter(Boolean));
const ranks=new Map((job.candidateRanks||[]).map(c=>[String(c.id),c.rank]));
// Apollo can return fewer matches than requested (and nulls for misses).
// Use only enriched business-email records; email verification happens next.
const candidates=matches.filter(m=>m && m.email && m.id)
 .map(m=>({...m,rank:ranks.get(String(m.id))||99}))
 .sort((a,b)=>a.rank-b.rank);
const selected=candidates.find(m=>!reservedOrContacted.has(String(m.email).trim().toLowerCase()));
const prior=existing.filter(r=>String(r.Company||'').toLowerCase()===String(job.Company).toLowerCase()&&String(r['Contacted At']||'').trim());
const history=prior.length?`New job at ${job.Company}; previously contacted: ${prior.map(x=>`${x.Name||x['Contact Name']} (${x.Email})`).join('; ')}`:'';
if(!selected)return [{json:{...job,hasContact:false,history,contactFailure:matches.length?'Apollo returned no unused business-email match':'Apollo bulk_match returned no matched people'}}];
const fullName=selected.name||`${selected.first_name||''} ${selected.last_name||''}`.trim();
return [{json:{...job,hasContact:true,Name:fullName,Title:selected.title||'','Contact Name':fullName,'Contact Title':selected.title||'','Contact Email':String(selected.email).trim().toLowerCase(),'LinkedIn URL':selected.linkedin_url||'','Email Verification':'pending',candidatePriority:selected.rank,history}}];

const j=$json;
const profileName=String(j.profileName||'').trim();
const profileBio=String(j.profileBio||'').trim();
if(!profileName||!profileBio||!j.resumeUrl||!j.portfolioUrl) throw new Error('Profile fields missing; check the portfolio endpoint.');
const system = `You are a careful, evidence-bound career outreach writer. Use only the supplied profile and actual job-posting text. Never invent skills, experience, education, metrics, eligibility, work authorisation or company facts. If the posting lacks a concrete detail or any required profile/link/name is missing, return [NEEDS-HUMAN] plus a reason. Return strict JSON only: {"subject":"...","body":"..."}. Body 60-120 words, 3-5 sentences, exactly one question mark; address recruiter by first name; include exact job title, one factual detail, both exact links, and this exact line: If this isn't relevant, just reply 'no' and I won't follow up. Avoid: I hope this email finds you well, game-changer, reach out, synergy, passionate. No placeholders.`;
const user = `PROFILE NAME: ${profileName}
PROFILE BIO (the only applicant-background facts you may use): ${profileBio}
TARGET ROLES: ${(j.profileRoles||[]).join(', ')}
LOCATION PREFERENCE: ${j.locationPreference||'India, remote, global'}
RESUME URL: ${j.resumeUrl}
PORTFOLIO URL: ${j.portfolioUrl}
RECIPIENT: ${j['Contact Name']} (${j['Contact Title']})
COMPANY: ${j.Company}
JOB TITLE: ${j['Job Title']}
JOB LINK: ${j['Job Link']}
POSTING TEXT: ${j['Posting Text']}`;
return [{json:{...j,profileName,profileBio,openaiBody:{model:($env.OPENAI_MODEL||'gpt-4.1-mini'),temperature:0.2,response_format:{type:'json_object'},messages:[{role:'system',content:system},{role:'user',content:user}]}}}];

// Hard deterministic gate. Run once for each draft item.
const j = $json;
const body = String(j.body ?? j.draft ?? j.emailBody ?? '').trim();
const expected = String(j.expectedEmail ?? j.apolloEmail ?? j['Contact Email'] ?? '').trim().toLowerCase();
const recipient = String(j.recipientEmail ?? j.to ?? j['Contact Email'] ?? '').trim().toLowerCase();
const verified = j.emailVerified === true || j['Email Verification'] === 'valid';
const words = body.match(/\b[\p{L}\p{N}][\p{L}\p{N}'’-]*\b/gu) ?? [];
const banned = ['i hope this email finds you well','game-changer','reach out','synergy','passionate'];
const lower = body.toLowerCase();
const bannedHits = banned.filter(p => lower.includes(p));
const placeholders = /\[[^\]]+\]|\{\{[^}]+\}\}|\b(?:YOUR_NAME|YOUR_EMAIL|RESUME_URL|PORTFOLIO_URL|COMPANY_NAME|RECRUITER_NAME)\b|REPLACE_WITH/i.test(body);
const resumeUrl=String(j.resumeUrl||''); const portfolioUrl=String(j.portfolioUrl||'');
const minWords = Number(j.minWords ?? 60);
const maxWords = Number(j.maxWords ?? 120);
const questionMarks = (body.match(/\?/g) ?? []).length;
const reasons = [];
if (!body) reasons.push('empty body');
if (words.length < minWords || words.length > maxWords) reasons.push(`word count ${words.length} outside ${minWords}-${maxWords}`);
if (questionMarks !== 1) reasons.push(`expected exactly one question mark; found ${questionMarks}`);
if (bannedHits.length) reasons.push(`banned phrase(s): ${bannedHits.join(', ')}`);
if (placeholders) reasons.push('leftover placeholder detected');
if (!/^https?:\/\//i.test(resumeUrl) || !body.includes(resumeUrl)) reasons.push('real resume URL missing from draft');
if (!/^https?:\/\//i.test(portfolioUrl) || !body.includes(portfolioUrl)) reasons.push('real portfolio URL missing from draft');
if (!expected || recipient !== expected) reasons.push('recipient does not match Apollo result');
if (!verified) reasons.push('email has not passed verification');
const sentences = body.split(/(?<=[.!?])\s+(?=[A-Z0-9"'(])/).filter(s => s.trim().length > 0).length;
if (sentences < 3 || sentences > 5) reasons.push(`sentence count ${sentences} outside 3-5`);
if (!body.includes("If this isn't relevant, just reply 'no' and I won't follow up.")) reasons.push('exact opt-out sentence missing');
if (j['Job Title'] && !lower.includes(String(j['Job Title']).toLowerCase())) reasons.push('exact job title missing from draft');
return [{json:{...j, body, wordCount:words.length, questionMarks, gatePassed:reasons.length===0, gateReasons:reasons}}];

