const logs=$input.all().map(x=>x.json); let candidate={};
for(const name of ['Normalize Approval Decision','Normalize Follow-Up Decision','Find Follow-Ups and Approved Deferred Sends']) { try { const x=$(name).item.json; if(x && (x['Job Link']||x.kind)) {candidate=x; break;} } catch(e){} }
const now=new Date(); const dateInIndia=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d); const today=dateInIndia(now);
const rampStartRaw=(typeof $env!=='undefined'&&$env.SEND_RAMP_START_DATE)?$env.SEND_RAMP_START_DATE:today; const rampStart=new Date(`${rampStartRaw}T00:00:00+05:30`); const todayStart=new Date(`${today}T00:00:00+05:30`); const elapsedDays=Math.max(0,Math.floor((todayStart-rampStart)/86400000)); const cap=elapsedDays<7?5:elapsedDays<14?10:elapsedDays<21?20:30;
const keys=new Set(); for(const r of logs){const stage=String(r.Stage??r.stage??'').toUpperCase();if(stage!=='SEND_RESERVED'&&stage!=='SEND_SUCCESS')continue;const ts=new Date(r.Timestamp??r.timestamp??'');if(Number.isNaN(ts.getTime())||dateInIndia(ts)!==today)continue;const link=String(r['Job Link']||'').trim();const email=String(r['Contact Email']||'').trim().toLowerCase();const key=(link&&email)?`${link}|${email}`:String(r['Message ID']||r['Execution ID']||`${stage}|${ts.toISOString()}`);keys.add(key);}
const sendsToday=keys.size; const liveSendsEnabled=String($env.LIVE_SENDS_ENABLED||'false').toLowerCase()==='true'; return [{json:{...candidate,canSend:liveSendsEnabled&&sendsToday<cap,liveSendsEnabled,sendsToday,dailyCap:cap,remainingToday:Math.max(0,cap-sendsToday),rampDay:elapsedDays+1,todayIndia:today}}];

let j;
try { j=$('Choose Unused Contact').item.json; }
catch (e) { j=$('Rank Apollo Candidates').item.json; }
return [{json:{'Job Link':j['Job Link'],'Status':'No New Contact','History':j.history||'','Last Error':j.contactFailure||(!j.hasCandidates?'Apollo returned no eligible candidate; no email will be sent':'No unused verified contact found among the first 10 Apollo candidates')}}];

let initial=null; let retry=null;
try{initial=$('Draft Code Gate #1').item.json;}catch(e){}
try{retry=$('Draft Code Gate #2').item.json;}catch(e){}
const chosen=initial?.gatePassed===true?initial:retry;
if(!chosen||chosen.gatePassed!==true)throw new Error('No validated draft reached the approval path.');
return [{json:chosen}];
